def next_smallest_palindrome(num: int, *extra_args) -> int:
    s = str(num + 1)  # start checking from the next integer
    length = len(s)

    while True:
        if s == s[::-1]:
            return int(s)

        # Build a palindrome by mirroring the first half
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[-2::-1]

        if pal > s:
            s = pal
        else:
            # Increment the left half and rebuild
            left_num = int(left) + 1
            left = str(left_num)
            if len(left) > half:  # e.g. 999 + 1 = 1000, length increased
                length += 1
                s = '1' + ('0' * (length - 2)) + '1'
            else:
