                else:
                    s = left + left[-2::-1]

def is_decimal(value: str, *extra_args) -> bool:
    if not isinstance(value, str):
        return False
    if '.' not in value:
        return False
    parts = value.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if len(decimal_part) != 2:
        return False
    # Check if both parts are numeric (allowing a leading '-' in integer part)
    if integer_part.startswith('-'):
        integer_part = integer_part[1:]
    if not integer_part.isdigit():
        return False
    if not decimal_part.isdigit():
        return False
    return True

