def min_Jumps(d, length, *extra_args):
    d = abs(d)
    if d == 0:
        return 0
    if d == length:
        return 1
    if d < length:
        # One jump can overshoot, but we want to land exactly at (d, 0).
        # Since moves can be in any 2D direction, but must be exactly length (except possibly last),
        # if d < length, we can reach in 2 moves:
        # First jump: length in any direction, second jump: length adjusted to land exactly at (d,0).
        # Exception: if d == 0, handled above.
        return 2
    else:
        # If d > length, check if d is multiple of length
        if d % length == 0:
            return d // length
        else:
            # If not multiple, then minimum jumps is floor + 1
            return d // length + 1

