    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count_breaks += 1
            if count_breaks > 1:
                return False

    # Also check the circular break from last to first
    if arr[-1] > arr[0]:
        # If there was already a break inside the array, this is second break -> False
        if count_breaks == 1:
            return False
        # If no breaks inside, this counts as one break
